import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Resources/app_fonts.dart';class FilterPage extends StatefulWidget {  const FilterPage({super.key});  @override  State<FilterPage> createState() => _FilterPageState();}class _FilterPageState extends State<FilterPage> {  List<String> categories(BuildContext context) => [        context.local.chair,        context.local.sofa,        context.local.table,        context.local.bed,        context.local.lamp,      ];  String? selectedCategory;  double price = 7500;  final double minPrice = 260;  final double maxPrice = 12000;  int selectedStars = 0;  void resetFilters() {    setState(() {      selectedCategory = categories(context).first;      price = minPrice;      selectedStars = 4;    });  }  Widget _buildTitle(String title) {    return Padding(      padding: EdgeInsets.only(bottom: 16.h),      child: Text(        title,        style: AppTextStyles.bodyLargeSemiBold,      ),    );  }  Widget _buildChoiceChip({    required String label,    required bool isSelected,    required VoidCallback onTap,  }) {    return ChoiceChip(      showCheckmark: false,      label: Text(label),      selected: isSelected,      selectedColor: AppColors.primaryColor,      backgroundColor: AppColors.backgroundColor,      labelStyle: AppTextStyles.bodySmallSemiBold.copyWith(        color: isSelected ? Colors.white : Colors.black,      ),      onSelected: (_) => onTap(),      labelPadding: EdgeInsets.symmetric(horizontal: 15, vertical: 12).w,      shape: RoundedRectangleBorder(        side: BorderSide(color: AppColors.grayscale30),        borderRadius: BorderRadius.circular(24).r,      ),    );  }  Widget _buildStarChip(int stars) {    return ChoiceChip(      label: Row(        mainAxisSize: MainAxisSize.min,        children: List.generate(stars, (_) {          return Icon(Icons.star, color: Colors.amber, size: 20);        }),      ),      labelPadding: EdgeInsets.symmetric(horizontal: 15, vertical: 12).w,      showCheckmark: false,      selected: selectedStars == stars,      selectedColor: AppColors.backgroundColor,      backgroundColor: AppColors.backgroundColor,      shape: RoundedRectangleBorder(        side: BorderSide(          color: selectedStars == stars              ? AppColors.primaryColor              : AppColors.grayscale30,        ),        borderRadius: BorderRadius.circular(30),      ),      onSelected: (_) => setState(() => selectedStars = stars),    );  }  @override  Widget build(BuildContext context) {    return Padding(      padding: EdgeInsets.symmetric(horizontal: 27).w,      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          // Header          Row(            mainAxisAlignment: MainAxisAlignment.spaceBetween,            children: [              Text(context.local.Filter, style: AppTextStyles.h6Bold),              TextButton(                onPressed: resetFilters,                child: Text(                  context.local.ResetFilters,                  style: AppTextStyles.h7Bold                      .copyWith(color: AppColors.primaryColor),                ),              ),            ],          ),          32.verticalSpace,          // Categories          _buildTitle(context.local.Categories),          Wrap(            spacing: 12,            runSpacing: 12,            children: categories(context).map((category) {              return _buildChoiceChip(                label: category,                isSelected: selectedCategory == category,                onTap: () => setState(() => selectedCategory = category),              );            }).toList(),          ),          24.verticalSpace,          // Price Slider          _buildTitle(context.local.Price),          Slider(            value: price,            min: minPrice,            max: maxPrice,            activeColor: AppColors.primaryColor,            inactiveColor: AppColors.grayscale20,            onChanged: (value) => setState(() => price = value),          ),          10.verticalSpace,          Row(            mainAxisAlignment: MainAxisAlignment.spaceBetween,            children: [              Text("\$$minPrice", style: TextStyle(fontSize: 14)),              Text("\$${price.toInt()}", style: TextStyle(fontSize: 14)),              Text("\$$maxPrice", style: TextStyle(fontSize: 14)),            ],          ),          24.verticalSpace,          // Star Rating          _buildTitle(context.local.StarRating),          Wrap(            spacing: 12,            runSpacing: 12,            children: List.generate(5, (index) => _buildStarChip(index + 1)),          ),          // Apply Button          Expanded(            child: Align(              child: ElevatedButton(                style: ElevatedButton.styleFrom(                  backgroundColor: AppColors.primaryColor,                  shape: RoundedRectangleBorder(                    borderRadius: BorderRadius.circular(24),                  ),                  minimumSize: Size(327.w, 56.h),                ),                onPressed: () {                  // Apply filter action                },                child: Text(                  context.local.ApplyFilters,                  style: AppTextStyles.h6Bold.copyWith(                    color: AppColors.backgroundColor,                  ),                ),              ),            ),          ),        ],      ),    );  }}